const body = $json.body ?? $json;
const data = body.data ?? {};
const key = data.key ?? {};
const message = data.message ?? {};

const event = String(body.event ?? '').toUpperCase().replace(/[.\-]/g, '_');
const rawJid = String(body.phone ?? key.remoteJid ?? '');
const altJid = String(
  key.remoteJidAlt ??
  key.participantAlt ??
  data.senderPn ??
  data.remoteJidAlt ??
  ''
);

let replyJid = rawJid;
if (rawJid.includes('@lid') && altJid) replyJid = altJid;
if (replyJid && !replyJid.includes('@') && /^\+?\d+$/.test(replyJid)) {
  replyJid = replyJid.replace(/\D/g, '') + '@s.whatsapp.net';
}

const phoneNumber = (replyJid || rawJid).replace(/\D/g, '');
const fromMe = body.from_me === true || key.fromMe === true;

let messageType = 'unsupported';
let text = String(
  body.message ??
  message.conversation ??
  message.extendedTextMessage?.text ??
  message.imageMessage?.caption ??
  message.videoMessage?.caption ??
  ''
).trim();

if (message.conversation || message.extendedTextMessage?.text || (text && !message.imageMessage && !message.audioMessage)) {
  messageType = 'text';
}
if (message.imageMessage) messageType = 'image';
if (message.audioMessage) messageType = 'audio';

const isGroup = rawJid.endsWith('@g.us');
const isBroadcast = rawJid.includes('@broadcast') || rawJid.includes('status@broadcast');
const validChat = !!body.company_id && !!body.instance_name && !!rawJid && !isGroup && !isBroadcast;
const isMessageEvent = event === 'MESSAGES_UPSERT' || event === 'MESSAGE_UPSERT';
const accessActive = body.access_active !== false &&
  ['trial','active'].includes(String(body.subscription_status ?? '').toLowerCase());

return [{
  json: {
    company_id: String(body.company_id ?? ''),
    company_name: String(body.company_name ?? ''),
    subscription_status: String(body.subscription_status ?? ''),
    access_active: accessActive,
    instance_name: String(body.instance_name ?? ''),
    event,
    message_id: String(body.message_id ?? key.id ?? ''),
    raw_jid: rawJid,
    reply_jid: replyJid,
    phone_number: phoneNumber,
    push_name: String(data.pushName ?? ''),
    from_me: fromMe,
    message_type: messageType,
    message_text: text,
    is_message_event: isMessageEvent,
    valid_chat: validChat,
    received_at: String(body.received_at ?? new Date().toISOString()),
    raw_data: data
  }
}];

const j = $json;

let text = '';
if (typeof j.text === 'string') text = j.text;
else if (Array.isArray(j) && j[0]?.content?.[0]?.text) text = j[0].content[0].text;
else if (j?.[0]?.content?.[0]?.text) text = j[0].content[0].text;
else if (j?.content?.[0]?.text) text = j.content[0].text;

text = String(text || '').trim();

const looksLikePixProof =
  /PIX_COMPROVANTE\s*:\s*SIM/i.test(text);

let description = text
  .replace(/PIX_COMPROVANTE\s*:\s*(SIM|NAO|NÃO)/ig, '')
  .replace(/^\s*DESCRICAO\s*:\s*/im, '')
  .trim();

if (!description) {
  description = 'Imagem enviada pelo cliente.';
}

return [{
  json: {
    message_text: `[Imagem enviada pelo cliente]\n${description}`,
    image_analysis: description,
    looks_like_pix_proof: looksLikePixProof
  }
}];

for (const item of items) {
  if (item.binary?.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return items;

let raw = $json.buffer;
let list = [];

if (Array.isArray(raw)) list = raw;
else if (typeof raw === 'string') {
  try {
    const parsed = JSON.parse(raw);
    list = Array.isArray(parsed) ? parsed : [raw];
  } catch {
    list = [raw];
  }
}

const parsed = list.map(v => {
  if (typeof v === 'object' && v) return v;
  try { return JSON.parse(String(v)); }
  catch { return {id:'', text:String(v ?? '')}; }
}).filter(v => String(v.text ?? '').trim());

const currentId = String($('Normalizar Evento').first().json.message_id ?? '');
if (!parsed.length) return [];

const last = parsed[parsed.length - 1];
if (String(last.id ?? '') !== currentId) return [];

const combined = parsed.map(v => String(v.text ?? '').trim()).filter(Boolean).join('\n');
return [{json:{message_text:combined, buffered_count:parsed.length}}];

const src = $json.output ?? $json;

function clean(v) {
  return String(v ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
}

function bool(v) {
  return v === true || v === 1 || String(v ?? '').trim().toLowerCase() === 'true';
}

function norm(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function money(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;

  let s = String(v).trim().replace(/\s/g, '').replace(/^R\$/i, '');

  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }

  s = s.replace(/[^\d.-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function brl(v) {
  return `R$ ${Number(v || 0).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`;
}

function parseMaybeJson(v) {
  if (!v || v === 'null') return null;
  if (typeof v === 'object') return v;

  try {
    const x = JSON.parse(String(v));
    return x && typeof x === 'object' ? x : null;
  } catch {
    return null;
  }
}

function deliveryType(v) {
  const s = norm(v);
  if (/\b(entrega|delivery|entregar)\b/.test(s)) return 'delivery';
  if (/\b(retirada|retirar|buscar|pickup)\b/.test(s)) return 'pickup';
  return '';
}

function payment(v) {
  const s = norm(v);
  if (/\bpix\b/.test(s)) return 'pix';
  if (/\b(dinheiro|cash)\b/.test(s)) return 'cash';
  if (/\b(cartao|credito|debito|card)\b/.test(s)) return 'card';
  return '';
}

function isClearConfirmation(v) {
  const s = norm(v);
  return /^(sim|confirmo|sim confirmo|pode confirmar|pode fechar|fechado|pode ser|isso|isso mesmo|correto|ta certo|ok|pode mandar|manda ver|pode finalizar)[.! ]*$/.test(s);
}

function isNo(v) {
  const s = norm(v);
  return /^(nao|não|nao precisa|não precisa|sem troco|nao quero|não quero|so isso|só isso|isso e tudo|isso é tudo)[.! ]*$/.test(s);
}

function isRealName(v) {
  const s = String(v ?? '').trim();
  return Boolean(
    s &&
    s.length >= 2 &&
    s.length <= 80 &&
    !/^cliente$/i.test(s) &&
    !/^unknown$/i.test(s) &&
    !/^desconhecido$/i.test(s) &&
    !/^\+?\d+$/.test(s)
  );
}

function extractName(v) {
  let s = String(v ?? '').trim();
  s = s.replace(/^(meu nome (?:é|e)|sou|pode me chamar de|me chama de)\s+/i, '').trim();

  if (!isRealName(s)) return '';
  if (/\d/.test(s)) return '';
  if (deliveryType(s) || payment(s) || isClearConfirmation(s) || isNo(s)) return '';

  if (!/^[A-Za-zÀ-ÖØ-öø-ÿ'´` -]+$/.test(s)) return '';
  return s;
}

function singleConfiguredFee(v) {
  const s = String(v ?? '').trim();
  if (!s) return null;

  const matches = s.match(/\d+(?:[.,]\d+)?/g) || [];
  const nums = matches
    .map(x => Number(x.replace(',', '.')))
    .filter(Number.isFinite);

  if (nums.length === 1) return nums[0];
  return null;
}

let out = src;

for (let i = 0; i < 3; i++) {
  if (out && typeof out === 'object' && !Array.isArray(out)) break;

  if (Array.isArray(out)) {
    out = out[0] ?? {};
    continue;
  }

  try {
    out = JSON.parse(clean(out));
  } catch {
    const s = clean(out);
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');

    if (a >= 0 && b > a) {
      try {
        out = JSON.parse(s.slice(a, b + 1));
      } catch {
        out = { resposta: s };
      }
    } else {
      out = { resposta: s };
    }
    break;
  }
}

const rawMessage = String(
  $('Consolidar Buffer').first().json.message_text ?? ''
).trim();
const msg = norm(rawMessage);

const catalog = Array.isArray($('Montar Catálogo Real').first().json.catalog)
  ? $('Montar Catálogo Real').first().json.catalog
  : [];

const byId = new Map(catalog.map(p => [String(p.id), p]));
const byName = new Map(catalog.map(p => [norm(p.name), p]));

let customer = {};
try {
  customer = $('Buscar Cliente Atual').first().json ?? {};
} catch {}

let shop = {};
try {
  shop = $('Buscar Loja Atual').first().json ?? {};
} catch {}

const savedCustomerName = String(
  customer.name ??
  customer.client_name ??
  customer.customer_name ??
  ''
).trim();

const previous = parseMaybeJson(
  $('Ler Rascunho do Pedido').first().json.order_draft
);

const recentConfirmedOrder = parseMaybeJson(
  $('Ler Pedido Confirmado Recente').first().json.recent_confirmed_order
);

const aiDraft =
  out.pedido && typeof out.pedido === 'object' && !Array.isArray(out.pedido)
    ? out.pedido
    : null;

function canonicalItem(raw) {
  if (!raw || typeof raw !== 'object') return null;

  const requestedId = String(raw.product_id ?? '').trim();
  const requestedName = String(raw.name ?? '').trim();

  const real =
    (requestedId && byId.get(requestedId)) ||
    (requestedName && byName.get(norm(requestedName))) ||
    null;

  if (!real) return null;

  return {
    product_id: String(real.id),
    name: String(real.name),
    quantity: Math.max(1, Math.trunc(Number(raw.quantity) || 1)),
    variation: String(raw.variation ?? ''),
    unit_price: money(real.price) ?? 0,
    notes: String(raw.notes ?? '')
  };
}

function mergeItems(a, b) {
  const map = new Map();

  for (const raw of [...(Array.isArray(a) ? a : []), ...(Array.isArray(b) ? b : [])]) {
    const item = canonicalItem(raw);
    if (!item) continue;

    const key = `${item.product_id}::${norm(item.variation)}`;
    map.set(key, item);
  }

  return [...map.values()];
}

function normalizeDraft(raw) {
  if (!raw || typeof raw !== 'object') return null;

  return {
    client_name: String(raw.client_name ?? '').trim(),
    items: mergeItems([], raw.items),
    observations: String(raw.observations ?? ''),
    delivery_type: deliveryType(raw.delivery_type),
    delivery_address: String(raw.delivery_address ?? '').trim(),
    payment_method: payment(raw.payment_method),
    change_for:
      raw.change_for === null || raw.change_for === undefined || raw.change_for === ''
        ? null
        : money(raw.change_for),
    delivery_fee:
      raw.delivery_fee === null || raw.delivery_fee === undefined || raw.delivery_fee === ''
        ? null
        : money(raw.delivery_fee)
  };
}

function mergeDraft(base, next) {
  const b = normalizeDraft(base) ?? {
    client_name: '',
    items: [],
    observations: '',
    delivery_type: '',
    delivery_address: '',
    payment_method: '',
    change_for: null,
    delivery_fee: null
  };

  const n = normalizeDraft(next);

  if (!n) return b.items.length ? b : null;

  return {
    client_name: isRealName(n.client_name) ? n.client_name : b.client_name,
    items: mergeItems(b.items, n.items),
    observations: n.observations || b.observations,
    delivery_type: n.delivery_type || b.delivery_type,
    delivery_address: n.delivery_address || b.delivery_address,
    payment_method: n.payment_method || b.payment_method,
    change_for: n.change_for !== null ? n.change_for : b.change_for,
    delivery_fee: n.delivery_fee !== null ? n.delivery_fee : b.delivery_fee
  };
}

let prev = normalizeDraft(previous);

// Nome de cliente recorrente é determinístico.
if (prev && !isRealName(prev.client_name) && isRealName(savedCustomerName)) {
  prev.client_name = savedCustomerName;
}

function missingField(p) {
  if (!p || !Array.isArray(p.items) || !p.items.length) return 'items';
  if (!isRealName(p.client_name)) return 'name';
  if (!['delivery', 'pickup'].includes(p.delivery_type)) return 'delivery_type';
  if (p.delivery_type === 'delivery' && !p.delivery_address) return 'address';
  if (!['pix', 'cash', 'card'].includes(p.payment_method)) return 'payment';

  if (
    p.payment_method === 'cash' &&
    (p.change_for === null || p.change_for === undefined)
  ) {
    return 'change';
  }

  if (
    p.delivery_type === 'delivery' &&
    (p.delivery_fee === null || p.delivery_fee === undefined)
  ) {
    return 'delivery_fee';
  }

  return null;
}

const stageBefore = missingField(prev);

// Junta rascunho anterior com o que a IA conseguiu extrair neste turno.
let pedido = mergeDraft(prev, aiDraft);

// Detecta produtos REAIS diretamente na mensagem.
// Isso é fallback; nunca cria produto fora do catálogo.
function productMatchesFromMessage() {
  const exact = [];
  const tokenMatches = [];

  const stop = new Set([
    'pizza','pizzas','com','sem','para','uma','umas','quero','manda',
    'mandar','pedir','pedido','por','favor','pfv','favor','de','da','do',
    'catupiry','queijo','grande','media','média','pequena'
  ]);

  for (const p of catalog) {
    const pname = norm(p.name);
    if (!pname) continue;

    if (msg.includes(pname)) {
      exact.push(p);
      continue;
    }

    const tokens = pname
      .split(/[^a-z0-9]+/)
      .filter(t => t.length >= 4 && !stop.has(t));

    const hits = tokens.filter(t => msg.includes(t));
    if (hits.length) {
      tokenMatches.push({ p, hits: hits.length });
    }
  }

  if (exact.length) return exact;

  if (tokenMatches.length === 1) {
    return [tokenMatches[0].p];
  }

  const best = tokenMatches.sort((a,b) => b.hits - a.hits);
  if (best.length && best[0].hits > (best[1]?.hits ?? 0)) {
    return [best[0].p];
  }

  return [];
}

const mentionedProducts = productMatchesFromMessage();

if (mentionedProducts.length) {
  const detected = mentionedProducts.map(real => {
    let quantity = 1;

    const pname = norm(real.name);
    const firstToken = pname.split(/[^a-z0-9]+/).find(t => t.length >= 4);
    if (firstToken) {
      const qre = new RegExp(`\\b(\\d+)\\s*(?:x\\s*)?(?:pizza[s]?\\s*)?${firstToken}\\b`, 'i');
      const qm = msg.match(qre);
      if (qm) quantity = Math.max(1, Number(qm[1]) || 1);
    }

    return {
      product_id: String(real.id),
      name: String(real.name),
      quantity,
      variation: '',
      unit_price: money(real.price) ?? 0,
      notes: ''
    };
  });

  pedido = pedido ?? {
    client_name: '',
    items: [],
    observations: '',
    delivery_type: '',
    delivery_address: '',
    payment_method: '',
    change_for: null,
    delivery_fee: null
  };

  pedido.items = mergeItems(pedido.items, detected);
}

// Se existe cliente com nome real, preenche sem depender da IA.
if (pedido && !isRealName(pedido.client_name) && isRealName(savedCustomerName)) {
  pedido.client_name = savedCustomerName;
}

// Captura determinística do dado que o workflow estava esperando.
// Assim a IA não pode "esquecer" de colocar nome/endereço/pagamento no JSON.
if (pedido && stageBefore === 'name' && !isRealName(pedido.client_name)) {
  const n = extractName(rawMessage);
  if (n) pedido.client_name = n;
}

if (pedido && stageBefore === 'delivery_type' && !pedido.delivery_type) {
  const t = deliveryType(rawMessage);
  if (t) pedido.delivery_type = t;
}

if (
  pedido &&
  stageBefore === 'address' &&
  pedido.delivery_type === 'delivery' &&
  !pedido.delivery_address
) {
  if (
    rawMessage.length >= 5 &&
    !payment(rawMessage) &&
    !deliveryType(rawMessage) &&
    !isClearConfirmation(rawMessage)
  ) {
    pedido.delivery_address = rawMessage;
  }
}

if (pedido && stageBefore === 'payment' && !pedido.payment_method) {
  const m = payment(rawMessage);
  if (m) pedido.payment_method = m;
}

if (
  pedido &&
  stageBefore === 'change' &&
  pedido.payment_method === 'cash' &&
  (pedido.change_for === null || pedido.change_for === undefined)
) {
  if (isNo(rawMessage)) {
    pedido.change_for = 0;
  } else {
    const m = rawMessage.match(/\d+(?:[.,]\d+)?/);
    if (m) pedido.change_for = money(m[0]);
  }
}

// Regras derivadas do tipo de entrega/pagamento.
if (pedido) {
  if (pedido.delivery_type === 'pickup') {
    pedido.delivery_address = '';
    pedido.delivery_fee = 0;
  }

  if (pedido.delivery_type === 'delivery' && pedido.delivery_fee === null) {
    const fee = singleConfiguredFee(shop.delivery_fee);
    if (fee !== null) pedido.delivery_fee = fee;
  }

  if (pedido.payment_method !== 'cash') {
    pedido.change_for = null;
  }
}

let missing = missingField(pedido);

function ask(field) {
  switch (field) {
    case 'items':
      return 'Me diz qual item do cardápio você quer pedir 😊';
    case 'name':
      return 'Como posso te chamar? 😊';
    case 'delivery_type':
      return 'Vai ser entrega ou retirada? 😊';
    case 'address':
      return 'Qual o endereço completo para entrega? 😊';
    case 'payment':
      return 'E como você prefere pagar: Pix, dinheiro ou cartão? 😊';
    case 'change':
      return 'Precisa de troco? Se sim, pra quanto? 😊';
    case 'delivery_fee':
      return 'Não consegui determinar a taxa de entrega com segurança. Vou chamar a equipe para te ajudar 😊';
    default:
      return 'Me confirma só mais um detalhe do pedido? 😊';
  }
}

function summary(p) {
  const itemLines = p.items.map(i =>
    `• ${i.quantity}x ${i.name} — ${brl((i.unit_price || 0) * i.quantity)}`
  );

  const subtotal = p.items.reduce(
    (s, i) => s + (Number(i.unit_price) || 0) * (Number(i.quantity) || 1),
    0
  );

  const fee = p.delivery_type === 'delivery'
    ? Number(p.delivery_fee || 0)
    : 0;

  const total = Math.round((subtotal + fee) * 100) / 100;

  const pay =
    p.payment_method === 'pix'
      ? 'Pix'
      : p.payment_method === 'cash'
        ? 'Dinheiro'
        : 'Cartão';

  const delivery =
    p.delivery_type === 'delivery'
      ? `Entrega — ${p.delivery_address}`
      : 'Retirada no local';

  const change =
    p.payment_method === 'cash'
      ? (
          Number(p.change_for) > 0
            ? `\n• Troco para ${brl(p.change_for)}`
            : '\n• Sem troco'
        )
      : '';

  return (
    `Fechado! 😊 Confere pra mim:\n\n` +
    `${itemLines.join('\n')}\n` +
    `• Subtotal — ${brl(subtotal)}\n` +
    (p.delivery_type === 'delivery' ? `• Taxa de entrega — ${brl(fee)}\n` : '') +
    `• Total — ${brl(total)}\n` +
    `• ${delivery}\n` +
    `• Pagamento — ${pay}${change}\n\n` +
    `Posso confirmar seu pedido?`
  );
}

let resposta = String(out.resposta ?? '').trim();
let status = String(out.status_lead ?? 'em_atendimento');
let enviarCardapio = bool(out.enviar_cardapio);
let transbordo = bool(out.transbordo);
let motivoTransbordo = String(out.motivo_transbordo ?? '');

// Cardápio: nunca manda URL como texto.
const nr = norm(resposta);
if (
  nr.includes('aqui esta nosso cardapio') ||
  nr.includes('aqui esta o nosso cardapio') ||
  nr.includes('segue nosso cardapio') ||
  nr.includes('segue o cardapio') ||
  (/https?:\/\/\S+/i.test(resposta) && /supabase|storage/i.test(resposta))
) {
  enviarCardapio = true;
}

if (enviarCardapio) {
  resposta = 'Oi! 😊 Aqui está nosso cardápio:';
}

// Se já há pedido, o estado determinístico manda no checkout.
let pedidoConfirmado = false;
const clearConfirmation = isClearConfirmation(rawMessage);

if (pedido && pedido.items.length) {
  // Não deixa a conversa pular campos.
  if (missing) {
    if (missing === 'delivery_fee') {
      transbordo = true;
      status = 'transbordo';
      motivoTransbordo = 'Taxa de entrega não pôde ser determinada';
    } else {
      transbordo = false;
      status = 'aguardando_dados';
    }

    resposta = ask(missing);
  } else if (clearConfirmation) {
    // CONFIRMAÇÃO É 100% DETERMINÍSTICA.
    pedidoConfirmado = true;
    transbordo = false;
    status = 'pedido_confirmado';
    motivoTransbordo = '';
    resposta = '__CRIAR_PEDIDO__';
  } else {
    // Pedido completo: o workflow gera o resumo, sem depender da IA.
    pedidoConfirmado = false;
    transbordo = false;
    status = 'aguardando_confirmacao';
    resposta = summary(pedido);
  }
}

// Nunca vaza marcadores técnicos, mesmo se a IA escrever.
if (/processando[_\s-]*pedido|__criar_pedido__/i.test(resposta) && !pedidoConfirmado) {
  resposta = missing ? ask(missing) : summary(pedido);
}

// Follow-up: só quando o pedido já está COMPLETO e ficou aguardando o "sim".
// Isso evita 5 Waits durante nome/endereço/pagamento.
let followupEligible =
  !!(
    pedido &&
    pedido.items.length &&
    !missing &&
    !pedidoConfirmado &&
    !transbordo
  );


// PROTEÇÃO PÓS-PEDIDO:
// a memória do agente pode lembrar o checkout anterior, mas um pedido já confirmado
// nunca pode ser reconstruído sozinho. Um novo pedido só nasce com produto real
// explicitamente mencionado na mensagem atual.
const hasDraftBeforeThisTurn =
  !!(
    previous &&
    Array.isArray(previous.items) &&
    previous.items.length
  );

const mentionsRealProductNow =
  Array.isArray(mentionedProducts) &&
  mentionedProducts.length > 0;

const hasRecentConfirmedOrder = !!recentConfirmedOrder;

if (
  hasRecentConfirmedOrder &&
  !hasDraftBeforeThisTurn &&
  !mentionsRealProductNow
) {
  pedido = null;
  missing = null;
  pedidoConfirmado = false;
  followupEligible = false;

  // Não deixa a memória repetir resumo/checkout/confirmação do pedido antigo.
  const responseNorm = norm(resposta);
  const looksLikeOldCheckout =
    responseNorm.includes('posso confirmar seu pedido') ||
    responseNorm.includes('confere pra mim') ||
    responseNorm.includes('confere para mim') ||
    responseNorm.includes('resumo do seu pedido') ||
    responseNorm.includes('subtotal') ||
    responseNorm.includes('taxa de entrega') ||
    responseNorm.includes('__criar_pedido__') ||
    responseNorm.includes('processando_pedido');

  if (looksLikeOldCheckout) {
    resposta = 'Seu pedido já foi confirmado 😊 Se precisar de algo sobre ele, pode me chamar por aqui.';
    status = 'em_atendimento';
    transbordo = false;
    motivoTransbordo = '';
  }
}

return [{
  json: {
    resposta,
    status_lead: status,
    enviar_cardapio: enviarCardapio,
    followup_eligible: followupEligible,
    transbordo,
    motivo_transbordo: motivoTransbordo,
    pedido_confirmado: pedidoConfirmado,
    pedido,
    validation_missing: missing
  }
}];

const p = $('Interpretar Resposta IA').first().json.pedido;
const catalog = Array.isArray($('Montar Catálogo Real').first().json.catalog)
  ? $('Montar Catálogo Real').first().json.catalog
  : [];

if (!p || !Array.isArray(p.items) || !p.items.length) {
  throw new Error('Pedido sem itens.');
}

function norm(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function num(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;

  let s = String(v).trim().replace(/\s/g, '').replace(/^R\$/i, '');
  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }

  s = s.replace(/[^\d.-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function realName(v) {
  const s = String(v ?? '').trim();
  return Boolean(
    s &&
    !/^cliente$/i.test(s) &&
    !/^unknown$/i.test(s) &&
    !/^desconhecido$/i.test(s)
  );
}

const byId = new Map(catalog.map(x => [String(x.id), x]));

const items = p.items.map(i => {
  const real = byId.get(String(i.product_id ?? '').trim());

  if (!real) {
    throw new Error(`Produto inexistente ou inativo: ${String(i.name ?? i.product_id ?? '')}`);
  }

  return {
    product_id: String(real.id),
    name: String(real.name),
    quantity: Math.max(1, Math.trunc(Number(i.quantity) || 1)),
    variation: String(i.variation ?? ''),
    unit_price: num(real.price),
    notes: String(i.notes ?? '')
  };
});

let customer = {};
try {
  customer = $('Buscar Cliente Atual').first().json ?? {};
} catch {}

const draftName = String(p.client_name ?? '').trim();
const savedName = String(customer.name ?? '').trim();
const pushName = String($('Normalizar Evento').first().json.push_name ?? '').trim();

// Estratégia da V1 restaurada: o pedido NÃO deixa de ser criado por causa do nome.
// Preferência: nome coletado > nome cadastrado > push_name > "Cliente".
// O trigger do Supabase faz o upsert do customer ao inserir delivery_orders.
const clientName =
  (realName(draftName) ? draftName : '') ||
  (realName(savedName) ? savedName : '') ||
  (realName(pushName) ? pushName : '') ||
  'Cliente';

const type = String(p.delivery_type ?? '').trim();
if (!['delivery', 'pickup'].includes(type)) {
  throw new Error('Tipo de entrega inválido.');
}

const address =
  type === 'pickup'
    ? ''
    : String(p.delivery_address ?? '').trim();

if (type === 'delivery' && !address) {
  throw new Error('Pedido para entrega sem endereço.');
}

const method = String(p.payment_method ?? '').trim();
if (!['pix', 'cash', 'card'].includes(method)) {
  throw new Error('Forma de pagamento inválida.');
}

if (
  method === 'cash' &&
  (p.change_for === null || p.change_for === undefined || p.change_for === '')
) {
  throw new Error('Pagamento em dinheiro sem informação de troco.');
}

const subtotal = items.reduce(
  (s, i) => s + i.unit_price * i.quantity,
  0
);

const deliveryFee =
  type === 'pickup'
    ? 0
    : num(p.delivery_fee);

const total = Math.round((subtotal + deliveryFee) * 100) / 100;

return [{
  json: {
    company_id: $('Normalizar Evento').first().json.company_id,
    client_name: clientName,
    client_phone: $('Normalizar Evento').first().json.phone_number,
    items,
    observations: String(p.observations ?? ''),
    delivery_type: type,
    delivery_address: address,
    total_value: total,
    status: 'Novos',
    payment_method: method,
    payment_status: method === 'pix' ? 'pending' : 'pay_on_delivery',
    change_for: method === 'cash' ? num(p.change_for) : null
  }
}];

const pendingRaw = String($json.review_pending ?? '').trim();
const text = String($('Consolidar Buffer').first().json.message_text ?? '').trim();

let ctx = {};
if (pendingRaw) {
  try { ctx = JSON.parse(pendingRaw); }
  catch { ctx = { order_id: pendingRaw }; }
}

const match = text.match(/^\s*([1-5])(?:[.,]0)?\s*$/);
const isRating = Boolean(pendingRaw && match);

return [{
  json: {
    is_rating: isRating,
    rating: isRating ? Number(match[1]) : null,
    order_id: String(ctx.order_id ?? ''),
    customer_id: String(ctx.customer_id ?? ''),
    customer_name: String(ctx.client_name ?? ''),
    company_name: String(ctx.company_name ?? $('Normalizar Evento').first().json.company_name ?? ''),
    company_instagram: String(ctx.company_instagram ?? ''),
    phone_number: $('Normalizar Evento').first().json.phone_number
  }
}];

const r = $('Interpretar avaliação pendente').first().json;
const rating = Number(r.rating || 0);
const companyName = String(r.company_name || 'a gente').trim();
let instagram = String(r.company_instagram || '').trim();

if (instagram) {
  instagram = instagram
    .replace(/^https?:\/\/(www\.)?instagram\.com\//i, '')
    .replace(/\/.*$/, '')
    .replace(/^@/, '')
    .trim();
}

let resposta;
if (rating >= 4) {
  const empresaTag = instagram ? `@${instagram}` : companyName;
  resposta = `Aee! 💙 Obrigado pela nota ${rating}/5. Se postar seu pedido, marca ${empresaTag} e @arlesdelivery pra gente ver 😄`;
} else {
  resposta = `Obrigado pela nota ${rating}/5 💙 Seu feedback ajuda a gente a melhorar.`;
}

return [{ json: { resposta } }];

const r = $('Interpretar Resposta IA').first().json;
return [{
  json: {
    should_followup:
      r.followup_eligible === true &&
      r.pedido_confirmado !== true &&
      r.transbordo !== true
  }
}];

const currentMessageId = String($('Normalizar Evento').first().json.message_id ?? '');
const lastInbound = String($('Ler última entrada').first().json.last_inbound ?? '');
const sent = String($json.followup_sent ?? '').trim();

return [{
  json: {
    can_send_followup: Boolean(currentMessageId && lastInbound === currentMessageId && !sent)
  }
}];

const p = $('Preparar Pedido').first().json;
let shop = {};
try {
  shop = $('Buscar Loja Atual').first().json ?? {};
} catch {}

const primeiroNome = String(p.client_name ?? '').trim().split(/\s+/)[0];
const nome = primeiroNome && !/^cliente$/i.test(primeiroNome)
  ? `, ${primeiroNome}`
  : '';

let resposta = `Fechou${nome}! ✅ Seu pedido foi confirmado e já está com a equipe. Vou te atualizando por aqui 😊`;

if (p.payment_method === 'pix') {
  const pix = String(shop.pix_key ?? '').trim();
  if (pix) {
    resposta += `\n\nPix: ${pix}\nDepois do pagamento, pode mandar o comprovante por aqui.`;
  }
}

return [{ json: { resposta } }];

function norm(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function money(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;

  let s = String(v).trim().replace(/\s/g, '').replace(/^R\$/i, '');
  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }

  s = s.replace(/[^\d.-]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

const rows = $input.all()
  .map(i => i.json ?? {})
  .filter(p => String(p.id ?? '').trim() && String(p.name ?? '').trim())
  .map(p => ({
    id: String(p.id).trim(),
    name: String(p.name).trim(),
    category: String(p.category ?? '').trim(),
    description: String(p.description ?? '').trim().slice(0, 180),
    price: money(p.price)
  }))
  .filter(p => p.price !== null);

const unique = [];
const seen = new Set();

for (const p of rows) {
  if (seen.has(p.id)) continue;
  seen.add(p.id);
  unique.push(p);
}

function scoreUpsell(p) {
  const s = norm(`${p.category} ${p.name}`);

  if (/(bebida|bebidas|refrigerante|refrigerantes|refri|coca|pepsi|guarana|fanta|sprite|suco|agua)/.test(s)) {
    return 100;
  }
  if (/(sobremesa|sobremesas|doce|doces|pudim|brownie|sorvete|acai)/.test(s)) {
    return 70;
  }
  if (/(acompanhamento|acompanhamentos|adicional|adicionais|porcao|porcoes|batata)/.test(s)) {
    return 40;
  }

  return 0;
}

const upsellCandidate = [...unique]
  .map(p => ({ ...p, _score: scoreUpsell(p) }))
  .filter(p => p._score > 0)
  .sort((a, b) => b._score - a._score || a.price - b.price)[0] ?? null;

const catalogForAI = unique.map(p => ({
  id: p.id,
  name: p.name,
  category: p.category,
  price: p.price,
  description: p.description
}));

return [{
  json: {
    catalog: unique,
    catalog_for_ai: catalogForAI,
    upsell_candidate: upsellCandidate
      ? {
          id: upsellCandidate.id,
          name: upsellCandidate.name,
          category: upsellCandidate.category,
          price: upsellCandidate.price
        }
      : null,
    product_count: unique.length
  }
}];

const rows = $input.all()
  .map(i => i.json ?? {})
  .filter(r => r && r.id);

const now = Date.now();
const MAX_AGE_MS = 8 * 60 * 60 * 1000;

const candidates = rows
  .filter(r => {
    if (String(r.payment_method ?? '').toLowerCase() !== 'pix') return false;

    const paymentStatus = String(r.payment_status ?? '').toLowerCase();
    if (!['pending', 'pending_approval'].includes(paymentStatus)) return false;

    const orderStatus = String(r.status ?? '').toLowerCase();
    if (['finalizados', 'cancelados'].includes(orderStatus)) return false;

    const created = new Date(r.created_at ?? 0).getTime();
    if (!Number.isFinite(created) || now - created > MAX_AGE_MS) return false;

    return true;
  })
  .sort((a, b) =>
    new Date(b.created_at ?? 0).getTime() -
    new Date(a.created_at ?? 0).getTime()
  );

const order = candidates[0] ?? null;

return [{
  json: {
    found: !!order,
    order_id: order?.id ?? '',
    payment_status: order?.payment_status ?? '',
    client_name: order?.client_name ?? '',
    total_value: order?.total_value ?? null,
    created_at: order?.created_at ?? null,
    order_status: order?.status ?? ''
  }
}];

const media = $('Baixar Imagem').first().json?.data ?? {};

let base64 = String(media.base64 ?? '').trim();
if (!base64) {
  throw new Error('A Evolution não retornou o base64 da imagem.');
}

let mime = String(
  media.mimetype ??
  media.mimeType ??
  media.contentType ??
  ''
).trim();

if (!/^image\//i.test(mime)) {
  mime = 'image/jpeg';
}

const paymentProofUrl = /^data:/i.test(base64)
  ? base64
  : `data:${mime};base64,${base64}`;

return [{
  json: {
    order_id: $('Selecionar Pedido PIX Pendente').first().json.order_id,
    payment_proof_url: paymentProofUrl,
    payment_status: 'pending_approval',
    updated_at: new Date().toISOString()
  }
}];
